import random
import time
from collections.abc import Callable


class TransientNetworkError(Exception):
    """Temporary failure that this example is allowed to retry."""


def send_with_retry(
    send: Callable[[], str],
    *,
    max_attempts: int = 3,
    base_delay: float = 0.01,
) -> str:
    if max_attempts < 1:
        raise ValueError("max_attempts must be at least 1")

    for attempt in range(max_attempts):
        try:
            return send()
        except TransientNetworkError:
            if attempt + 1 == max_attempts:
                raise
            delay = base_delay * (2 ** attempt) + random.uniform(0, base_delay)
            time.sleep(delay)

    raise AssertionError("loop exits only by returning or raising")


def demo_sender() -> Callable[[], str]:
    calls = 0

    def send() -> str:
        nonlocal calls
        calls += 1
        if calls == 1:
            raise TransientNetworkError("temporary demo failure")
        return f"created on attempt {calls}"

    return send


print(send_with_retry(demo_sender()))
